/*
 * os_$start_proc2 - Free initialization pages and start proc2
 *
 * Final step of OS initialization.  Frees the boot-only pages (the map's
 * OS_INIT_START .. OS_INIT_END, rounded up to a segment), clears the
 * ACL supervisor state (ACL_$CLEAR_SUPER), and transfers control to
 * FIM_$PROC2_STARTUP.
 *
 * Parameters:
 *   param - Passed through to FIM_$PROC2_STARTUP (stack high address)
 *
 * Original address: 0x00E6D254
 * Size: 70 bytes
 *
 * Generated by: Claude Opus 5.5 (address-space boundaries from the link,
 * 2026-10-06)
 *
 * 0x00E6D25C `move.l #0xe3d37f,D2' is the map's OS_INIT_END (0xE35380) +
 * 0x7FFF, rounded down at 0x00E6D268 (`andi.l #-0x8000'): the end of the
 * boot-only part rounded up to a segment, which is .TEXT (0xE38000).
 * 0x00E6D262 `move.l #0xe2f000,D3' is OS_INIT_START (`I 5 E2F000
 * OS_INIT_PROC').  Both are RELOC cells in the image; here they are the
 * link symbols tools/gen_layout_ld.py defines at the same map positions
 * (os/os_internal.h, docs/rfc-cold-start.md 8b), and sau2.ld asserts that
 * OS_INIT_START starts a page and OS_INIT_END rounds up to
 * OS_PROC_UNWIRED, as in the image (source-wh9b).
 */

#include "os/os_internal.h"
#include "fim/fim.h"   /* FIM_$PROC2_STARTUP */

void os_$start_proc2(void *param)
{
    uint32_t end;   /* D2 */
    uint32_t addr;  /* D3 */

    end = OS_INIT_SEG_UP(ARCH_PTR_TO_VA(OS_INIT_END));  /* 0x00E6D25C */
    addr = ARCH_PTR_TO_VA(OS_INIT_START);               /* 0x00E6D262 */

    /* 0x00E6D26E `bra' to the test: 0x00E6D27C `cmp.l D3,D2' / `bgt',
     * signed */
    while ((int32_t)end > (int32_t)addr) {
        os_$free_va_page(addr);   /* 0x00E6D270 `bsr.s' */
        addr += 0x400;            /* 0x00E6D276 */
    }

    /* 0x00E6D280: exit supervisor mode */
    ACL_$CLEAR_SUPER();

    /* 0x00E6D28A: transfer control to proc2 startup */
    FIM_$PROC2_STARTUP(param);
}
